// Claude returns its answer in content[0].text — extract and parse the JSON.
const raw = $input.first().json.content[0].text;
const jsonStr = raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1);
const story = JSON.parse(jsonStr);
const inputs = $('Story Inputs').first().json;

// Build a URL slug from the title
const slug = story.title
  .toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-|-$/g, '');

return [{ json: {
  slug,
  title: story.title,
  excerpt: story.excerpt,
  language: inputs.language,
  age_range: inputs.ageRange,
  genre: inputs.genre,
  theme: inputs.theme,
  body: story.body,
  quiz: story.quiz,
  glossary: story.glossary,
  image_prompt: story.imagePrompt,
  status: 'published',
  reading_minutes: Math.max(2, Math.round((story.body.join(' ').split(/\s+/).length) / 140)),
  created_at: new Date().toISOString()
} }];
